+ * globally by the Reference layout; tokens come from lab-tokens.css. */

 /* Inline prose code that contains a highlighted tag drops its own grey plate so
    only the painted tokens show (the runtime highlighter swaps the <code>'s text
    for tk-* spans). */
 .content code:has([class^="tk-"]),
 .content .code:has([class^="tk-"]) { background: transparent; padding: 0; }

